// Reads directly from OpenClaw host installation. No extra DB or manual config needed.
// Follows MVP principle: simple, reliable, zero-config for standard installs.

import fs from 'fs';
import path from 'path';

export type Agent = {
  id: string;
  name: string;
  workspace: string;
  model?: string;
  ui?: {
    emoji: string;
    color: string;
  };
};

const OPENCLAW_DIR = process.env.OPENCLAW_DIR || '/root/.openclaw';

const CONFIG_PATH = path.join(OPENCLAW_DIR, 'openclaw.json');

export function getAgents(): Agent[] {
  try {
    if (!fs.existsSync(CONFIG_PATH)) {
      console.warn('⚠️ openclaw.json not found. Using fallback agents.');
      return [{ id: 'main', name: 'Main Agent', workspace: 'workspace' }];
    }

    const config = JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf8'));
    return config.agents?.list || [];
  } catch (error) {
    console.error('Failed to load agents:', error);
    return [];
  }
}

export async function getAgentById(id: string): Promise<Agent | null> {
  const agents = getAgents();
  return agents.find(a => a.id === id) || null;
}
