import { Agent, getAgents } from '@/lib/agents';

export function useAgents(pollInterval = 10000) {
  const [agents, setAgents] = useState<Agent[]>([]);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    try {
      const freshAgents = getAgents();
      // In real implementation we would merge with live status
      setAgents(freshAgents);
    } catch (err) {
      console.error('Failed to refresh agents', err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refresh();
    const interval = setInterval(refresh, pollInterval);

    return () => clearInterval(interval);
    // Clean up on unmount - important for dashboard
  }, [refresh, pollInterval]);

  return {
    agents,
    loading,
    refresh
  };
}
