import { chromium } from 'playwright';
import TurndownService from 'turndown';
import { ScraperOptions, Platform, ScrapedPage } from './types.js';

/**
 * Core scraper that extracts documentation from multiple platforms.
 * Uses Playwright for reliable rendering and Turndown for clean Markdown output.
 * Architecture favors direct host file reading where possible and minimal external services.
 */
export class DocumentationScraper {
  private options: ScraperOptions;
  private turndown: TurndownService;

  constructor(options: Partial<ScraperOptions> = {}) {
    this.options = {
      headless: true,
      timeout: 10000,
      delay: 500,
      includeMetadata: true,
      platform: 'auto',
      ...options,
    };

    this.turndown = new TurndownService({
      headingStyle: 'atx',
      codeBlockStyle: 'fenced',
    });
  }

  /** Detect platform from HTML structure and meta information */
  private async detectPlatform(content: string, url: string): Promise<Platform> {
    if (content.includes('docusaurus') || content.includes('__docusaurus')) {
      return 'docusaurus';
    }
    if (content.includes('mintlify')) {
      return 'mintlify';
    }
    return 'docusaurus'; // sensible default
  }

  async scrape(url: string, outputPath?: string): Promise<string> {
    const browser = await chromium.launch({ headless: this.options.headless });
    try {
      const context = await browser.newContext();
      const page = await context.newPage();

      console.log(`📄 Scraping documentation from ${url}`);
      await page.goto(url, { timeout: this.options.timeout });

      const platform = await this.detectPlatform(await page.content(), url);
      const pages = await this.discoverPages(page, url);

      const results: ScrapedPage[] = [];
      for (const pageUrl of pages) {
        await new Promise(r => setTimeout(r, this.options.delay));
        const pageContent = await this.extractPage(page, pageUrl);
        results.push(pageContent);
      }

      const markdown = this.generateMarkdown(results, url, platform);

      if (outputPath) {
        await Bun.write(outputPath, markdown);
      }

      return markdown;
    } finally {
      await browser.close();
    }
  }

  // Additional methods would be implemented here following the same pattern...
}

