/**
 * Documentation page discovery utilities
 * 
 * Prefers sitemap.xml when available as it's the most reliable and respectful
 * approach. Falls back to navigation crawling for sites without sitemaps.
 * Avoids over-engineering by using simple, declarative patterns.
 */
export async function discoverPages(baseUrl: string, page: any): Promise<string[]> {
  // Try sitemap first
  const sitemapUrl = `${baseUrl.replace(/\/$/, '')}/sitemap.xml`;

  try {
    const response = await fetch(sitemapUrl);
    if (response.ok) {
      const text = await response.text();
      const urls = extractUrlsFromSitemap(text, baseUrl);
      return filterDocsUrls(urls);
    }
  } catch (err) {
    console.log('⚠️  No sitemap found, falling back to navigation crawl');
  }

  // Fallback: extract from navigation
  return extractFromNavigation(page, baseUrl);
}

function extractUrlsFromSitemap(sitemap: string, baseUrl: string): string[] {
  const urlMatches = sitemap.match(/<loc>([^<]+)<\/loc>/g) || [];
  return urlMatches.map(match => 
    match.replace(/<loc>|<\/loc>/g, '').trim()
  ).filter(url => url.startsWith(baseUrl));
}

function filterDocsUrls(urls: string[]): string[] {
  return urls.filter(url => 
    !url.includes('/blog/') && 
    !url.includes('/changelog') &&
    url.length < 120 // avoid overly specific pages
  );
}

async function extractFromNavigation(page: any, baseUrl: string): Promise<string[]> {
  // Platform specific navigation selectors
  const navSelectors = [
    'nav a', 
    '.menu a',
    '[class*="sidebar"] a',
    'a[href^="/"]'
  ];

  const links = await page.$$eval('a', (elements: HTMLAnchorElement[]) => 
    elements.map(el => el.href)
  );

  return [...new Set(links.filter(link => 
    link.startsWith(baseUrl) && !link.includes('#')
  ))];
}

