/**
 * Content extraction for different documentation platforms
 * Uses declarative selector mapping rather than complex conditionals
 * to keep the code clean and easy to extend for new platforms.
 */

const PLATFORM_SELECTORS = {
  docusaurus: {
    content: 'article, .markdown, main',
    title: 'h1, .theme-doc-title',
    ignore: ['nav', 'footer', '.theme-doc-sidebar']
  },
  mintlify: {
    content: '.content, .prose, main',
    title: 'h1, .mintlify-title',
    ignore: ['.sidebar', 'header', 'footer']
  }
};

export async function extractMainContent(page: any, platform: 'docusaurus' | 'mintlify'): Promise<{title: string; html: string}> {
  const selectors = PLATFORM_SELECTORS[platform];

  const title = await page.$eval(selectors.title, (el: Element) => el.textContent?.trim() || 'Untitled')
    .catch(() => 'Documentation');

  const html = await page.$eval(selectors.content, (el: Element) => el.outerHTML)
    .catch(() => '<p>No content found</p>');

  return { title, html };
}

export function cleanHtml(html: string, platform: string): string {
  // Remove elements that shouldn't be in documentation
  return html
    .replace(/<script.*?>.*?</script>/gis, '')
    .replace(/<style.*?>.*?</style>/gis, '')
    .replace(/class="[^"]*"/g, '')
    .trim();
}

