import { useMemo } from 'react';
import type { Task } from '@/lib/types';

interface FilterOptions {
  search: string;
  status: 'all' | 'pending' | 'completed';
  tags: string[];
}

// MVP: Only essential filtering logic. No over-engineering.
export function useTaskFilters(tasks: Task[], options: FilterOptions) {
  return useMemo(() => {
    let result = [...tasks];

    // Search filter
    if (options.search) {
      const term = options.search.toLowerCase();
      result = result.filter(task => 
        task.title.toLowerCase().includes(term) || 
        task.description?.toLowerCase().includes(term)
      );
    }

    // Status filter
    if (options.status !== 'all') {
      result = result.filter(task => task.status === options.status);
    }

    // Tag filter
    if (options.tags.length > 0) {
      result = result.filter(task => 
        task.tags.some(tag => options.tags.includes(tag.id))
      );
    }

    return result;
  }, [tasks, options]);
}

